/* Entropy Overhaul: Endless -- the run (appended to server/model/BreedDungeon, so it shares that module's scope:
   exports.ModelBreedDungeon, Xlsx_1, P, Dungeon_1, ServerUtils_1, Util_1, WindowUtil_1, Player_1,
   BreedDungeonPreparePhases_1, csharp_1). Generated into mod.json by build_grim.py; edit src/endless_run.js.

   An Endless run is a single-player Extreme run started with the Endless tab selected (HeatUtil.EndlessSelected; the
   choice is mirrored to globalThis.__ENDLESS_SEL and kept in PlayerPrefs BBEE_ENDLESS_SELECTED). It never ends by itself:
   - BreedDungeonConf.maxPhase reads 999 for that run (a getter on the row, so every client and server check agrees);
     when the player leaves at a gate it reads the current stage, so the stock ending and settlement run as a clear;
   - stages 7+ get PhaseConf rows (stage 6's levels, the themes of stages 1-4 in turn) and a layout built on demand from
     the stage 1-4 generators with a new seed per depth; the boss pool past stage 6 only leaves out the boss killed last;
   - a gate after stage 6 and after every 5th stage (10, 15, 20 ...): continue deeper, or leave;
   - records (best depth per character, runs in progress, Grim cleared) live in a sidecar file in the account folder,
     never in the save. The engine was proven by the dev probe (mods/endless-probe; DESIGN.md 6.6-6.7);
   - 0.10.0 (DESIGN 6.9): an Endless run follows every Grim rule, carried on to 200 Entropy. The rules are flags on the
     run model, set when the run starts (build_grim.py GRIM_RUN_DETECT); E.flags restores them for a run continued from a
     save, and the per-room code (boss level, Mutation count) reads them through here.
   Every step logs to modlog.txt as "ENDLESS ...". */
;(function () {
  "use strict";
  var E = globalThis.__ENDLESS = globalThis.__ENDLESS || {};
  var VERSION = "1.0.6", LOGF = "@ROOT@/modlog.txt";
  var STOCK_MAX = 6, ENDLESS_MAX = 999, LAST_ROW = 300, TEMPLATES = 4;
  var IDS = [1003, 3004];          // single-player Extreme (PC / console tables); co-op keeps the stock run
  var SEL_KEY = "BBEE_ENDLESS_SELECTED", GRIM_SEL_KEY = "BBEE_GRIM_SELECTED", SIDE = "redux_endless.json";
  var RULES = {"bossLv0":176,"cap":175,"endlessCap":200,"floorIds":[17000950,17000977],"depthFns":[17000996,17000997]};             // boss level base, Grim's and Endless's caps, the floor function id range
  var nlog = 0;
  function log(m) {
    if (nlog++ > 400) return;
    try { csharp_1.System.IO.File.AppendAllText(LOGF, new Date().toISOString() + " ENDLESS " + m + "\n") } catch (x) {}
  }
  E.version = VERSION; E.log = log; E.mem = E.mem || {}; E.leaving = E.leaving || {}; E.asked = E.asked || {};

  /* after a hot load this module copy has its own, empty ModelBreedDungeon; the game keeps the one it loaded first,
     which require() still returns (2026-10-17, game: window 4) */
  function model() {
    var m = exports.ModelBreedDungeon.Instance;
    if (m && m.data && m.data.baseInfo && m.data.baseInfo.actorId) return m;
    try { var live = require("Server/Model/BreedDungeon").ModelBreedDungeon.Instance; if (live) return live } catch (x) {}
    return m;
  }
  function run() {                                   // the saved run, without creating one
