     own saved tab, so a guest left on Grim played Grim rules in an Extreme lobby (testers, 2026-10-22 00:25) */
  var TEAM_IDS = [2003, 4004];
  function fightGrimMode() {
    try { var h = require("GamePlay/BattleTeamBreedRun/BattleTeamBreedGlobalRef").BattleTeamBreedGlobalRef.TeamPveHeatData; if (h && h.BB4 && h.BB4.grimMode != null) return h.BB4.grimMode | 0 } catch (x) {}
