    if (m.__grimRun == null) {
      var expert = false; try { expert = m.conf.mode == P.EBreedDungeonMode.Expert } catch (x) {}
      var tm = null; try { tm = E.teamMode(m.baseInfo) } catch (x) {}
      var endless = expert && (tm != null ? tm == 105 : E.isEndless());
      m.__endlessRun = !!endless; m.__grimRun = !!(expert && (endless || hasFloor(m)));
      log("rules restored for a continued run: " + (m.__endlessRun ? "Endless" : m.__grimRun ? "Grim" : "stock"));
