  E.bossPrefix = function () {
    try {
      var f = E.flags(model()); if (!f.grim) return null;
      var U = Util_1.U, stock = String(U.GetLocale("Battle_ExpertMode") || ""), name = U.GetLocale(f.endless ? "BattleModeName_105" : "BattleModeName_104");
      if (!name) return null;
