  };
  E.model = model;
  E.reload = function (m) { if (m) { m.__grimRun = undefined; m.__endlessRun = undefined } };
  /* the boss trigger's level: Grim's curve (176 + Entropy), to 175 in Grim and 200 in Endless; undefined = stock */
  E.bossLevel = function (m) {
    var f = E.flags(m); if (!f.grim) return undefined;
    var h = 0; try { h = m.baseInfo.heat || 0 } catch (x) {}
