  var GATE = [{"id":24,"vals":[12,8],"ranks":[[17000301],[17000302]],"badge":1},{"id":25,"vals":[25,50,100],"ranks":[[17000201],[17000202],[17000203]],"badge":1},{"id":26,"vals":[3,4,5],"ranks":[[17000101],[17000102],[17000103]],"badge":1},{"id":27,"vals":[1,2,2],"ranks":[[17000401],[17000402,17000404],[17000403,17000404]],"badge":1},{"id":28,"vals":[25,18,12],"ranks":[[17000601],[17000602],[17000603]]},{"id":29,"vals":[3,1,1],"ranks":[[17000701],[17000702],[17000703]]},{"id":30,"vals":[45],"ranks":[[17000801,17000802]]},{"id":31,"vals":[30,50],"ranks":[[17000851,17000861],[17000852,17000862]]},{"id":32,"vals":[50],"ranks":[[17000871,17000872]]}];               // Grim's Abyss rows: {id, ranks: [[function ids of rank 1], ...], vals: [menu value per rank]}
